<?php use App\Core\Authorization; ?>
<div class="page-heading"><div><p class="eyebrow">Monitoring</p><h1>Events</h1><p>Schedule activities, register participants, and monitor attendance.</p></div><?php if(Authorization::allows('events.create')):?><a class="button primary" href="<?=e(url('/events/create'))?>">Create event</a><?php endif;?></div>
<form class="filter-bar" method="get" aria-label="Filter events"><label class="filter-field">Search<input name="q" value="<?=e($q)?>" placeholder="Event title or venue"></label><label class="filter-field">Status<select name="status"><option value="">All statuses</option><?php foreach(['draft','published','ongoing','completed','cancelled'] as $s):?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=e(ucfirst($s))?></option><?php endforeach;?></select></label><button class="button">Search events</button></form>
<div class="event-grid"><?php foreach($events as $event):?><article class="card event-card"><div class="event-date"><strong><?=e(date('d',strtotime($event['starts_at'])))?></strong><span><?=e(date('M Y',strtotime($event['starts_at'])))?></span></div><div class="event-card-main"><div class="event-meta"><span class="badge"><?=e($event['status'])?></span><span><?=e($event['visibility'])?></span></div><h2><a href="<?=e(url('/events/'.$event['id']))?>"><?=e($event['title'])?></a></h2><p><?=e(date('M j, Y g:i A',strtotime($event['starts_at'])))?> · <?=e($event['venue']?:'Venue not set')?></p><small><?=e($event['organizer'])?> · <?=(int)$event['participant_count']?> participants</small></div><?php if(Authorization::allows('events.edit')):?><div class="event-card-actions"><a class="button event-edit-button" href="<?=e(url('/events/'.$event['id'].'/edit'))?>">Edit event</a></div><?php endif;?></article><?php endforeach;?><?php if(!$events):?><section class="card empty">No events found.</section><?php endif;?></div>
